def apply_theme():
    st.markdown('<style>'+ (ROOT/'assets/dashboard.css').read_text()+'</style>', unsafe_allow_html=True)

def page_intro(page):
    p=PAGES[page]
    st.markdown(f'<section class="hero"><div><div class="eyebrow">GREEN INVENTORY / {p["number"]} / {html.escape(page.upper())}</div><h1>{p["title"]}</h1><p>{p["description"]}</p><div class="hero-tags"><span class="pill"><span class="status-dot"></span>LOCAL RESEARCH WORKSPACE</span><span class="pill">FORECAST → PLAN → MEASURE</span></div></div>{NETWORK}</section>',unsafe_allow_html=True)
    st.markdown('<div class="guide-strip">'+''.join(f'<div class="guide-cell"><b>{label}</b><p>{p[key]}</p></div>' for label,key in [('WHAT YOU SEE','depicts'),('WHAT YOU CAN DO','action'),('HOW TO READ IT','interpretation')])+'</div>',unsafe_allow_html=True)
    with st.expander(f'Page guide · {page}'):
        for title,text in p['details']:
            st.markdown(f'**{title}** — {text}')

def footer():
    st.markdown('<div class="footer-note"><span>GREEN INVENTORY · DECISION SUPPORT</span><span>Historical sales · Illustrative operations · Auditable outcomes</span></div>',unsafe_allow_html=True)
